// Generated by Suite Builder from a crawl of the site. The coordinator: many agents on one backlog, one story each (G-216).
// EDIT RULES: do not edit this file; regenerating replaces all of it. Your Jira names go in jira-loop/jira.properties (jira login fills them in).
// The coordinator (G-216): many agents on one backlog, one story each, without stepping on each other.
//   node jira-loop/agents.mjs work      one agent: take a ready story, run the crew on it, propose it as its
//                                       own branch and pull request; then the next, until none is left
//   node jira-loop/agents.mjs merged    on main, after a merge: each merged story reported done, its locks freed
//   node jira-loop/agents.mjs need <file>   the crew asking for a shared file before it changes it (exit 2: held)
//   node jira-loop/agents.mjs locks     who holds what
// How agents keep off each other's feet:
//  - A story is claimed in Jira before it is worked on (G-215): two agents never take the same one.
//  - New files never conflict. A file that already exists, changed by a story (a page class, a helper), is
//    locked for that story until its pull request merges: a git ref, refs/suite-locks/<file>, pushed
//    without force, so only one push can make it. An agent that needs a file another story holds waits for
//    that merge; one waiting too long puts its story back in the queue and takes another.
//  - The next story an agent takes is one whose pages no other story holds, when there is one.
//  - After a wait, the story is done again on the newest main, so it never merges over another's change.
// Settings, from the pipeline: SUITE_CREW (the crew's command, {key} the story), SUITE_CHECKS (the suite's
// checks, one a line), SUITE_PROPOSE (opens the pull request: {branch}, {key}, {title}), SUITE_AGENT (a name),
// SUITE_WAIT_MINUTES (how long to wait for a file, 20), SUITE_LOCK_HOURS (a lock older is stale, 6).
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SYNC = join(ROOT, 'jira-loop', 'sync.mjs');
const AGENT = process.env.SUITE_AGENT || `agent-${process.pid}`;
// The crew's own calls (need) are this agent's: they inherit its name.
process.env.SUITE_AGENT = AGENT;
const WAIT_MS = Number(process.env.SUITE_WAIT_MINUTES || 20) * 60_000;
const STALE_MS = Number(process.env.SUITE_LOCK_HOURS || 6) * 3_600_000;
const POLL_MS = Number(process.env.SUITE_POLL_SECONDS || 15) * 1000;
const EMPTY_TREE = '4b825dc642cb6eb9a060e54bf8d69288fbee4904';
const LOCKS = 'refs/suite-locks';

const say = (line) => console.log(`[${AGENT}] ${line}`);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** git, in the suite's folder: its output, or null when it failed. */
function git(...args) {
  const run = spawnSync('git', args, { cwd: ROOT, encoding: 'utf8' });
  return run.status === 0 ? run.stdout.trim() : null;
}

/** jira-loop/sync.mjs: its exit code and output. */
function sync(...args) {
  const run = spawnSync(process.execPath, [SYNC, ...args], { cwd: ROOT, encoding: 'utf8' });
  return { code: run.status ?? 1, out: `${run.stdout}${run.stderr}`.trim() };
}

/** A command of the pipeline's (the crew, a check, the proposal), with the story's names filled in. */
function shell(template, values) {
  const command = template.replace(/\{(\w+)\}/g, (_, k) => values[k] ?? '');
  return spawnSync(command, { cwd: ROOT, shell: true, stdio: 'inherit', env: { ...process.env, SUITE_STORY: values.key } }).status ?? 1;
}

// ---- Locks: one git ref a file, made by a push without force, so only one push can make it ----

const lockRef = (file) => `${LOCKS}/${file.replace(/[^A-Za-z0-9._/-]/g, '_')}`;

/** Every lock: its file, the story holding it, and since when. */
function locks() {
  const out = git('ls-remote', 'origin', `${LOCKS}/*`) ?? '';
  return out.split('\n').filter(Boolean).map((line) => {
    const [sha, ref] = line.split('\t');
    git('fetch', '-q', 'origin', `${ref}:${ref}`);
    const [key = '?', at = '0', agent = '?'] = (git('log', '-1', '--format=%s', sha) ?? '').split(' ');
    return { file: ref.slice(LOCKS.length + 1), ref, key, at: Number(at), agent };
  });
}

/** A file locked for a story: true when it holds it now (made, or already its own). */
function lock(file, key) {
  const ref = lockRef(file);
  const sha = git('commit-tree', EMPTY_TREE, '-m', `${key} ${Date.now()} ${AGENT}`);
  if (sha && git('push', '-q', 'origin', `${sha}:${ref}`) !== null) return true;
  const held = locks().find((l) => l.ref === ref);
  if (!held) return false;
  if (held.key === key && held.agent === AGENT) return true;
  // A lock left by an agent that stopped: older than SUITE_LOCK_HOURS, taken over.
  if (Date.now() - held.at > STALE_MS) {
    say(`${file}: ${held.key}'s lock is stale; taken over`);
    git('push', '-q', 'origin', `:${ref}`);
    return lock(file, key);
  }
  return false;
}

/** Every lock a story holds, freed. */
function release(key) {
  for (const l of locks().filter((x) => x.key === key)) git('push', '-q', 'origin', `:${l.ref}`);
}

// ---- Which pages a story touches, from its words, to keep two stories off one page at once ----

/** The suite's page classes: each file under a folder named pages, with the words of its name. */
function pageFiles() {
  const files = (git('ls-files') ?? '').split('\n').filter((f) => /(^|\/)pages\//.test(f) && /\.(java|ts|js|txt)$/.test(f));
  return files.map((f) => {
    const name = f.split('/').pop().replace(/\.\w+$/, '').replace(/(Page|Elements|Actions|Tasks)$/, '');
    return { file: f, words: name.replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase().split(/[\s_-]+/).filter(Boolean) };
  });
}

/** The page files a story's words name. */
function pagesOf(text, pages) {
  const words = new Set(text.toLowerCase().split(/[^a-z0-9]+/));
  return pages.filter((p) => p.words.length && p.words.every((w) => words.has(w))).map((p) => p.file);
}

// ---- One agent ----

/** What the crew decided for the story in this working copy: implemented, pushed back, or nothing. */
function decided(key) {
  const done = join(ROOT, 'stories', 'done');
  const file = existsSync(done) ? readdirSync(done).find((f) => f.toUpperCase().startsWith(`${key} `) || f.toUpperCase() === `${key}.TXT`) : null;
  if (file) {
    const text = readFileSync(join(done, file), 'utf8');
    const at = text.lastIndexOf('---- IMPLEMENTED');
    if (at >= 0) return /^Not implemented:(?!\s*none\b)/im.test(text.slice(at)) ? 'waiting' : 'implemented';
  }
  return sync('pending').out.includes(`"key":"${key}"`) ? 'pushed back' : 'nothing';
}

/** The files a story changed that existed before it: the ones another story could also change. */
function changedShared() {
  return (git('diff', '--name-only') ?? '').split('\n').filter((f) => f && !f.startsWith('stories/') && !f.startsWith('jira-loop/'));
}

/** The working copy back on the newest main, nothing of the last story left. */
function fresh() {
  git('fetch', '-q', 'origin', 'main');
  git('checkout', '-q', '-B', 'work', 'origin/main');
  git('reset', '-q', '--hard', 'origin/main');
  git('clean', '-qfd', '-e', 'secrets/');
}

/** Waits for every file locked for the story; false when one stays held past SUITE_WAIT_MINUTES. */
async function lockAll(files, key) {
  const until = Date.now() + WAIT_MS;
  for (const file of files) {
    while (!lock(file, key)) {
      if (Date.now() > until) return false;
      const by = locks().find((l) => l.ref === lockRef(file))?.key ?? 'another story';
      say(`${key}: waits for ${file} (${by} holds it until its pull request merges)`);
      await sleep(POLL_MS);
    }
  }
  return true;
}

/** The story's file as pulled, to put back when it is done again on a newer main. */
function storyFile(key) {
  const dir = join(ROOT, 'stories', 'new');
  const name = readdirSync(dir).find((f) => f.toUpperCase().startsWith(`${key} `));
  return name && { name, text: readFileSync(join(dir, name), 'utf8') };
}

/** The story's file put back after the working copy was reset to the newest main. */
function restore(pulled) {
  if (!pulled) return;
  mkdirSync(join(ROOT, 'stories', 'new'), { recursive: true });
  writeFileSync(join(ROOT, 'stories', 'new', pulled.name), pulled.text);
}

/** One story, start to proposal. `pages`: the page classes its words name, locked before the crew starts. */
async function workOn(key, title, pages = []) {
  const values = { key, title, branch: `stories/${key}` };
  const pulled = storyFile(key);
  // Waiting for a page now costs less than doing the story twice: the crew starts on the newest main.
  if (pages.length) {
    if (!(await lockAll(pages, key))) {
      sync('unclaim', key, `${AGENT} waited more than ${WAIT_MS / 60_000} minutes for ${pages.join(', ')}.`);
      release(key);
      return 'requeued';
    }
    fresh();
    restore(pulled);
  }
  for (let attempt = 1; attempt <= 3; attempt++) {
    const base = git('rev-parse', 'HEAD');
    if (shell(process.env.SUITE_CREW || 'claude -p "/stories {key}"', values) !== 0) say(`${key}: the crew stopped with an error`);
    const outcome = decided(key);
    if (outcome !== 'implemented') {
      if (outcome === 'nothing') sync('unclaim', key, `${AGENT}'s crew decided nothing; another agent may try.`);
      else sync('report', key);
      say(`${key}: ${outcome}${outcome === 'nothing' ? '; back in the queue' : '; reported'}`);
      release(key);
      return outcome;
    }
    const shared = changedShared();
    if (!(await lockAll(shared, key))) {
      sync('unclaim', key, `${AGENT} waited more than ${WAIT_MS / 60_000} minutes for ${shared.join(', ')}.`);
      release(key);
      say(`${key}: waited too long for a shared file; back in the queue`);
      return 'requeued';
    }
    // Another story changed one of these files on main while this one worked: done again on top of it.
    git('fetch', '-q', 'origin', 'main');
    const moved = shared.length ? git('diff', '--name-only', base, 'origin/main', '--', ...shared) : '';
    if (moved) {
      say(`${key}: ${moved.split('\n').join(', ')} changed on main meanwhile; the story is done again on top (attempt ${attempt + 1})`);
      fresh();
      restore(pulled);
      continue;
    }
    for (const check of (process.env.SUITE_CHECKS ?? '').split('\n').filter(Boolean)) {
      if (shell(check, values) !== 0) {
        sync('unclaim', key, `the suite's checks failed on ${AGENT}'s tests (${check}); another agent may try.`);
        release(key);
        say(`${key}: checks failed; back in the queue`);
        return 'requeued';
      }
    }
    git('switch', '-q', '-C', values.branch);
    git('add', '-A', '--', '.', ':!jira-loop/reported.json');
    git('commit', '-q', '-m', `${key}: ${title}`, '-m', `Tests written by the suite's crew (${AGENT}).`);
    if (git('push', '-q', '-f', 'origin', `HEAD:refs/heads/${values.branch}`) === null) return 'push failed';
    if (process.env.SUITE_PROPOSE) shell(process.env.SUITE_PROPOSE, values);
    sync('note', key, `Tests proposed: branch ${values.branch}. The card moves to done when it merges.`);
    say(`${key}: proposed as ${values.branch}`);
    return 'proposed';
  }
  sync('unclaim', key, 'done again three times, and main kept moving under it.');
  release(key);
  return 'requeued';
}

/** An agent: stories, one at a time, until none is left to take. */
async function work() {
  const tally = {};
  const tried = new Set();
  for (;;) {
    fresh();
    const q = sync('queue');
    if (q.code !== 0) {
      say(q.out);
      return 1;
    }
    const pages = pageFiles();
    const held = new Set(locks().map((l) => l.file));
    // Stories whose pages no one holds first; then the rest, oldest first.
    const queue = JSON.parse(q.out).filter((s) => !tried.has(s.key));
    const free = queue.filter((s) => pagesOf(s.text, pages).every((f) => !held.has(f)));
    const next = [...free, ...queue.filter((s) => !free.includes(s))];
    let took = null;
    for (const s of next) {
      // The story's own lock first, then the claim in Jira: two agents never take one story, however close.
      if (!lock(`story/${s.key}`, s.key)) continue;
      if (sync('take', s.key).code === 0) {
        took = s;
        break;
      }
      release(s.key);
    }
    if (!took) break;
    tried.add(took.key);
    const title = took.text.split('\n')[0];
    say(`${took.key}: taken (${title})`);
    const outcome = await workOn(took.key, title, pagesOf(took.text, pages));
    tally[outcome] = (tally[outcome] ?? 0) + 1;
  }
  say(`done: ${Object.entries(tally).map(([k, v]) => `${v} ${k}`).join(', ') || 'nothing to take'}. Thank you.`);
  return 0;
}

/** On main after a merge: each story merged reported done in Jira, and its locks freed. */
function merged() {
  const pending = JSON.parse(sync('pending').out || '[]');
  const report = sync('report');
  console.log(report.out);
  for (const p of pending) if (p.done) release(p.key);
  return report.code;
}

const [command, arg] = process.argv.slice(2);
if (command === 'work') process.exitCode = await work();
else if (command === 'merged') process.exitCode = merged();
else if (command === 'need' && arg && process.env.SUITE_STORY) {
  // The crew, before changing a file that already exists and other stories may change too.
  const ok = lock(arg, process.env.SUITE_STORY);
  console.log(ok ? `${arg}: yours until ${process.env.SUITE_STORY} merges.` : `${arg}: held by ${locks().find((l) => l.ref === lockRef(arg))?.key ?? 'another story'}: change something else, or finish without it and say so.`);
  process.exitCode = ok ? 0 : 2;
} else if (command === 'locks') {
  for (const l of locks()) console.log(`${l.file}  ${l.key}  since ${new Date(l.at).toISOString()}`);
} else {
  console.log('node jira-loop/agents.mjs work | merged | need <file> | locks   (what each does: the top of this file)');
  process.exitCode = command ? 1 : 0;
}
